  static int BrightCentre(byte[] pixels){int count=0;for(int y=344;y<376;y++)for(int x=624;x<656;x++){int i=(y*1280+x)*3;if(pixels[i]>175&&pixels[i+1]>175&&pixels[i+2]>175)count++;}return count;}
